alter table public.work_tasks add column if not exists completed_at timestamptz;
alter table public.work_tasks add column if not exists reminder_at timestamptz;
alter table public.work_tasks add column if not exists recurrence_parent_id uuid references public.work_tasks(id) on delete set null;
create index if not exists work_tasks_due_idx on public.work_tasks(organization_id,due_at) where archived_at is null;
create or replace function public.complete_task_and_schedule_next(target_task_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare source_task public.work_tasks%rowtype; declare next_id uuid; declare interval_days int; begin select * into source_task from public.work_tasks where id=target_task_id; if source_task.id is null then raise exception 'task not found'; end if; if source_task.creator_id<>auth.uid() and source_task.assignee_id<>auth.uid() then raise exception 'not allowed'; end if; update public.work_tasks set status='done',completed_at=now() where id=target_task_id; if source_task.recurrence is null then return null; end if; interval_days:=case source_task.recurrence when 'daily' then 1 when 'weekly' then 7 else 30 end; insert into public.work_tasks(organization_id,creator_id,assignee_id,title,description,priority,status,start_at,due_at,labels,recurrence,recurrence_parent_id) values(source_task.organization_id,source_task.creator_id,source_task.assignee_id,source_task.title,source_task.description,source_task.priority,'todo',coalesce(source_task.start_at,current_date)+interval_days,case when source_task.due_at is null then null else source_task.due_at+interval_days end,source_task.labels,source_task.recurrence,source_task.id) returning id into next_id; return next_id; end; $$;
grant execute on function public.complete_task_and_schedule_next(uuid) to authenticated;
